'use strict';
const fs = require('node:fs');
const path = require('node:path');

function renderLauncher(source) {
  const entry = 'if (require.main === module) void main();';
  if (!source.includes(entry)) throw new Error('Launcher entry point is missing.');
  // A quoted heredoc passes JavaScript literally, regardless of the user's cwd.
  return `#!/bin/zsh
# Generated by build-macos-inspector-launcher.js; safe to move as a single file.
set -u
# Only the Finder-style, argument-free Terminal launch waits for a key.
launcher_interactive=0
if [[ -t 0 && -t 1 && $# -eq 0 && "\${TERM_PROGRAM:-}" == Apple_Terminal ]]; then
  launcher_interactive=1
fi
function finish_launcher() {
  local launcher_exit=$?
  trap - EXIT
  if (( launcher_interactive )); then
    local launcher_tty="$(/usr/bin/tty)"
    print
    print -r -- '按回车关闭启动器窗口（不会退出 Codex）。如窗口未关闭，请按 ⌘W。'
    local launcher_reply
    IFS= read -r launcher_reply || true
    # Close only this terminal's single-tab window after its shell has exited.
    # Never close another tab or quit the Terminal application.
    trap '' HUP
    /usr/bin/nohup /usr/bin/osascript - "$launcher_tty" </dev/null >/dev/null 2>&1 <<'CODEX_REMOTE_CLOSE_WINDOW' &
on run argv
  delay 1
  tell application "Terminal"
    repeat with launcherWindow in windows
      if (count of tabs of launcherWindow) is 1 then
        if tty of selected tab of launcherWindow is (item 1 of argv) then
          close launcherWindow
          return
        end if
      end if
    end repeat
  end tell
end run
CODEX_REMOTE_CLOSE_WINDOW
  fi
  exit "$launcher_exit"
}
trap finish_launcher EXIT
launcher_node="$(command -v node || true)"
if [[ -z "$launcher_node" && -x /usr/local/bin/node ]]; then launcher_node=/usr/local/bin/node; fi
if [[ -z "$launcher_node" && -x /opt/homebrew/bin/node ]]; then launcher_node=/opt/homebrew/bin/node; fi
if [[ -z "$launcher_node" ]]; then
  print -r -- '未找到 Node.js 22 或更新版本。请安装后再运行启动器。'
  exit 1
fi
"$launcher_node" - "$@" <<'CODEX_REMOTE_LAUNCHER_JS'
${source.replace(entry, 'void main();')}
CODEX_REMOTE_LAUNCHER_JS
`;
}

if (require.main === module) {
  const source = fs.readFileSync(path.join(__dirname, 'start-codex-with-inspector-macos.js'), 'utf8');
  const output = path.join(__dirname, '启动Codex.command');
  fs.writeFileSync(output, renderLauncher(source), { mode: 0o755 });
  fs.chmodSync(output, 0o755);
  console.log(`Generated standalone launcher: ${output}`);
}
module.exports = { renderLauncher };
